// ---------- Kacheln ----------
function relief(g,tx,ty,px,py){const a=G.hgt(tx,ty),b=G.hgt(tx+1,ty+1),s=(a-b)*.45;if(s>0.01){g.fillStyle=`rgba(255,250,220,${Math.min(.28,s)})`;g.fillRect(px,py,TILE,TILE);}else if(s<-0.01){g.fillStyle=`rgba(0,0,20,${Math.min(.32,-s)})`;g.fillRect(px,py,TILE,TILE);}}
const vnz=(x,y,sd)=>{const x0=Math.floor(x),y0=Math.floor(y),fx=x-x0,fy=y-y0,sx=fx*fx*(3-2*fx),sy=fy*fy*(3-2*fy);const a=h2(x0,y0,sd),b=h2(x0+1,y0,sd),c=h2(x0,y0+1,sd),d=h2(x0+1,y0+1,sd);return a+(b-a)*sx+(c-a)*sy+(a-b-c+d)*sx*sy;};
function crack(g,tx,ty,px,py,col,p){if(h2(tx,ty,150)>p)return;g.strokeStyle=col;g.lineWidth=1;g.beginPath();let x=px+4+h2(tx,ty,151)*24,y=py+4+h2(tx,ty,152)*24;g.moveTo(x,y);for(let i=0;i<3;i++){x+=(h2(tx,ty,153+i)-.5)*14;y+=(h2(tx,ty,156+i)-.5)*14;g.lineTo(Math.max(px+1,Math.min(px+31,x)),Math.max(py+1,Math.min(py+31,y)));}g.stroke();}
function patch(g,tx,ty,px,py,green){for(let j=0;j<8;j++)for(let i=0;i<8;i++){const x=tx+i/8+.0625,y=ty+j/8+.0625;const n=vnz(x*.45,y*.45,301),m=vnz(x*1.3,y*1.3,302);let k=(n-.5)*.26+(m-.5)*.12+(h2(tx*8+i,ty*8+j,305)-.5)*.05;
 if(green){const yl=Math.max(0,vnz(x*.28,y*.28,303)-.6)*1.5;if(yl>0.02){g.fillStyle=`rgba(190,165,60,${Math.min(.2,yl*.45)})`;g.fillRect(px+i*4,py+j*4,4,4);}}
 g.fillStyle=k>0?`rgba(255,248,220,${k*.5})`:`rgba(10,20,0,${-k*.7})`;g.fillRect(px+i*4,py+j*4,4,4);}}
function tufts(g,tx,ty,px,py,col){const n=3+Math.floor(h2(tx,ty,230)*3);for(let k=0;k<n;k++){const x=px+3+h2(tx,ty,200+k)*25,y=py+6+h2(tx,ty,210+k)*23;g.fillStyle=shade(col,-28);g.fillRect(x,y-3,1.5,4);g.fillRect(x+2,y-4,1.5,5);g.fillRect(x+4,y-2,1.5,3);g.fillStyle=shade(col,22);g.fillRect(x+2,y-5,1.5,2);g.fillRect(x,y-4,1.5,1.5);}}
// v21: verschiedene Baumarten (Eiche, Birke, Kiefer, Weide, Ahorn, Kirsche, Riese, dunkle Tanne, dürrer Baum)
