function drawTreeObj(g,tx,ty,px,py){const b=G.biome(tx,ty),r=h2(tx,ty,11);if(b==='winter')return;const kind=G.treeKind?G.treeKind(tx,ty):'oak';
  if(kind==='pine'||(b==='swamp'&&kind!=='willow'&&kind!=='birch')){g.fillStyle='#3a2616';g.fillRect(px+14,py+23,4,8);const base=b==='forest'?[28,72,38]:b==='dark'?[22,48,32]:[48,72,44];for(let i=0;i<4;i++){const w=17-i*3.6,yy=py+26-i*7.5,k=.82+i*.09;const col=`rgb(${base[0]*k|0},${base[1]*k|0},${base[2]*k|0})`;g.fillStyle=col;g.beginPath();g.moveTo(px+16,yy-9);g.lineTo(px+16-w,yy);g.lineTo(px+16+w,yy);g.closePath();g.fill();g.fillStyle='rgba(255,250,200,.16)';g.beginPath();g.moveTo(px+16,yy-9);g.lineTo(px+16-w,yy);g.lineTo(px+14,yy);g.closePath();g.fill();g.fillStyle='rgba(0,20,10,.22)';g.beginPath();g.moveTo(px+16,yy-9);g.lineTo(px+16+w,yy);g.lineTo(px+18,yy);g.closePath();g.fill();}return;}
  if(kind==='willow'){g.fillStyle='#4a3a22';g.fillRect(px+14,py+14,5,16);const base=TREECOL.willow;g.fillStyle=`rgb(${base})`;g.beginPath();g.ellipse(px+16,py+8,16,10,0,0,7);g.fill();g.strokeStyle=`rgb(${base[0]*1.15|0},${base[1]*1.15|0},${base[2]*1.1|0})`;g.lineWidth=1.6;for(let i=0;i<11;i++){const x=px+2+i*2.8,l=10+h2(tx,ty,140+i)*12;g.beginPath();g.moveTo(x,py+6);g.quadraticCurveTo(x+1.5,py+10+l*.5,x-1,py+8+l);g.stroke();}return;}
  const S=kind==='giant'?1.55:1,trunk=kind==='birch'?'#e8e4da':kind==='dark'?'#2a2018':'#4a3220';const base=TREECOL[kind]||(b==='forest'?[44,88,36]:[54,108,40]);
  g.save();g.translate(px+16,py+30);g.scale(S,S);g.translate(-16,-30);g.fillStyle=trunk;g.fillRect(14,17,5,13);g.fillRect(17,21,6,2);if(kind==='birch'){g.fillStyle='#2a2a2a';for(let i=0;i<4;i++)g.fillRect(14+(i%2)*2,18+i*3,3,1);}
  const bl=kind==='dry'?[[16,10,8],[24,8,5],[8,9,5]]:[[16,12,13],[26,15,9.5],[6,15,10],[16,3,10],[24,6,7],[8,6,7]];bl.forEach((q,i)=>{const k=.82+i*.09+r*.1;g.fillStyle=`rgb(${base[0]*k|0},${base[1]*k|0},${base[2]*k|0})`;g.beginPath();g.arc(q[0],q[1],q[2],0,7);g.fill();g.fillStyle='rgba(0,25,5,.22)';g.beginPath();g.arc(q[0]+q[2]*.35,q[1]-q[2]*.3,q[2]*.72,0,7);g.fill();g.fillStyle='rgba(255,250,200,.18)';g.beginPath();g.arc(q[0]-q[2]*.4,q[1]+q[2]*.15,q[2]*.5,0,7);g.fill();});
  if(kind==='cherry'){g.fillStyle='#fff0f6';for(let i=0;i<10;i++)g.fillRect(4+h2(tx,ty,160+i)*24,2+h2(tx,ty,170+i)*20,2,2);}
  g.fillStyle='rgba(0,0,0,.12)';for(let i=0;i<6;i++)g.fillRect(5+h2(tx,ty,120+i)*22,3+h2(tx,ty,130+i)*16,2,2);g.restore();}
// v21: Natur-Schicht: hohes Gras, Gestrüpp, Riesenbüsche, große Blumen
function drawDeco(g,tx,ty,px,py,v){const b=G.biome(tx,ty),dk=b==='dark'||b==='mist'?.7:b==='forest'?.85:1;const gc=(r,gg,bb,k)=>`rgb(${r*dk*k|0},${gg*dk*k|0},${bb*dk*k|0})`;
 if(v===1){for(let i=0;i<9;i++){const x=px+3+h2(tx,ty,400+i)*26,y=py+10+h2(tx,ty,410+i)*20,hh=9+h2(tx,ty,420+i)*8,l=(h2(tx,ty,430+i)-.5)*5;g.strokeStyle=gc(84,150,52,.8+h2(tx,ty,440+i)*.4);g.lineWidth=1.5;g.beginPath();g.moveTo(x,y);g.quadraticCurveTo(x+l*.3,y-hh*.6,x+l,y-hh);g.stroke();}if(b==='swamp'){g.fillStyle='#5a3a1e';for(let i=0;i<2;i++)g.fillRect(px+8+i*12,py+4+i*3,3,7);}return;}
 if(v===2||v===3){const S=v===3?1.7:1,cx=px+16,cy=py+20;g.fillStyle='rgba(0,0,0,.18)';g.beginPath();g.ellipse(cx+3,cy+6*S,14*S,5*S,0,0,7);g.fill();const n=v===3?9:6;for(let i=0;i<n;i++){const a=i/n*6.283+h2(tx,ty,450)*3,rr=(5+h2(tx,ty,460+i)*4)*S,bx=cx+Math.cos(a)*7*S,by=cy-4*S+Math.sin(a)*4*S-(i%3)*2*S;g.fillStyle=gc(52,104,40,.75+h2(tx,ty,470+i)*.4);g.beginPath();g.arc(bx,by,rr,0,7);g.fill();}g.fillStyle=gc(70,130,50,1.05);g.beginPath();g.arc(cx-2*S,cy-9*S,6*S,0,7);g.fill();
  if(v===2){g.strokeStyle=gc(60,46,30,1);g.lineWidth=1;for(let i=0;i<4;i++){const x=cx-10+i*7;g.beginPath();g.moveTo(x,cy+4);g.lineTo(x+(i%2?4:-4),cy-8);g.stroke();}}
  else if(h2(tx,ty,480)<.4){g.fillStyle='#d8304a';for(let i=0;i<6;i++)g.fillRect(cx-12+h2(tx,ty,490+i)*24,cy-18+h2(tx,ty,495+i)*18,2.5,2.5);}return;}
 if(v===4){const cols=['#f8c818','#e8281e','#9a7ae0','#f05a8a','#ffffff','#3a6ae8'],c=cols[Math.floor(h2(tx,ty,500)*cols.length)];for(let i=0;i<3;i++){const x=px+7+i*9+h2(tx,ty,510+i)*3,y=py+26,hh=12+h2(tx,ty,520+i)*8;g.strokeStyle='#4a8a3a';g.lineWidth=2;g.beginPath();g.moveTo(x,y);g.lineTo(x,y-hh);g.stroke();g.fillStyle='#4a8a3a';g.beginPath();g.ellipse(x+3,y-hh*.45,3.5,1.6,.5,0,7);g.fill();g.fillStyle=c;for(let k=0;k<6;k++){const a=k/6*6.283;g.beginPath();g.ellipse(x+Math.cos(a)*3.2,y-hh+Math.sin(a)*3.2,2.6,1.7,a,0,7);g.fill();}g.fillStyle='#6a4a1a';g.beginPath();g.arc(x,y-hh,2,0,7);g.fill();}}}
R.dirtyTile=(tx,ty)=>{const cx=Math.floor(tx/CH),cy=Math.floor(ty/CH);for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++){const qx=Math.floor((tx+dx)/CH),qy=Math.floor((ty+dy)/CH);chunks.delete(qx+','+qy);}};
const ANX2=new Map();for(const b of G.BUILD){if(b.annex==='barrels')ANX2.set((b.x-1)+','+(b.y+b.h-1),'barrels');if(b.annex==='woodpile')ANX2.set((b.x+b.w)+','+(b.y+1),'woodpile');if(b.annex==='rack')ANX2.set((b.x-1)+','+(b.y+b.h-1),'rack');}
