 const wallTile=(stone)=>{const below=G.tileAt(tx,ty+1);const front=below!==T.IWALL&&below!==T.SWALL&&below!==T.VOID&&below!==T.DOOR;g.fillStyle=stone?'#3a3734':'#3f2a16';g.fillRect(px,py,TILE,TILE);
  g.fillStyle=stone?'#4e4a45':'#5a3d20';if(stone){for(let j=0;j<4;j++)for(let i=0;i<2;i++)g.fillRect(px+(j%2?8:0)+i*16+1,py+j*8+1,14,6);}else{for(let i=0;i<4;i++)g.fillRect(px+i*8+1,py,6,TILE);}
  if(front){g.fillStyle=stone?'#2a2826':'#2a1a0c';g.fillRect(px,py+TILE-6,TILE,6);if(h2(tx,ty,77)<.28){g.fillStyle='#3a2a18';g.fillRect(px+14,py+12,4,10);g.fillStyle='#ffb040';g.beginPath();g.arc(px+16,py+10,4,0,7);g.fill();g.fillStyle='#fff3b0';g.beginPath();g.arc(px+16,py+11,2,0,7);g.fill();}}};
