  for(let i=0;i<6;i++){ctx.fillStyle=i%2?'#f5f5f5':b.roof;ctx.beginPath();ctx.moveTo(x-4+i*(w+8)/6,y-2);ctx.lineTo(x-4+(i+1)*(w+8)/6,y-2);ctx.lineTo(x-4+(i+1)*(w+8)/6,y+16);ctx.lineTo(x-4+i*(w+8)/6,y+16);ctx.fill();}
