 if(b.annex==='oven'){const ox=x-26,oy=y+h-30;ctx.fillStyle='#9a6a52';ctx.beginPath();ctx.arc(ox,oy+10,18,Math.PI,0);ctx.fill();ctx.fillRect(ox-18,oy+10,36,12);ctx.fillStyle='#1a1008';ctx.fillRect(ox-7,oy+8,14,12);ctx.fillStyle=`rgba(255,140,40,${.6+Math.sin(G.time*7)*.2})`;ctx.fillRect(ox-5,oy+14,10,5);}
 if(b.annex==='pen'){const px2=x-4.2*TILE,pz=y+.2*TILE,pw=3.4*TILE,pd=3*TILE;ctx.strokeStyle='#6a4a2a';ctx.lineWidth=3;ctx.strokeRect(px2,pz,pw,pd);for(let i=0;i<3;i++){const sx2=px2+26+i*29,sy=pz+30+(i%2)*32;ctx.fillStyle='#f0ece4';ctx.beginPath();ctx.ellipse(sx2,sy,11,8,0,0,7);ctx.fill();ctx.fillStyle='#2a2420';ctx.beginPath();ctx.arc(sx2+10,sy-1,4,0,7);ctx.fill();}}
 if(b.chimney){ctx.fillStyle='#7a6a5a';ctx.fillRect(x+w-26,y-14,10,16);if(Math.random()<.3)G.parts.push({x:x+w-21,y:y-16,z:0,vx:G.rnd(-6,6),vy:-25,life:1.2,c:'rgba(200,200,200,.5)',smoke:1});}
