 ctx.fillStyle='#4a3018';const dx=x+w/2-10;ctx.fillRect(dx,y+h-30,20,28);ctx.fillStyle='#c9a86a';ctx.fillRect(dx+14,y+h-17,3,3);
 if(b.kind!=='chapel'){ctx.fillStyle='#3b5a7a';for(const wx of [x+12,x+w-30]){ctx.fillRect(wx,y+h-26,16,12);ctx.strokeStyle='#5a3d1e';ctx.lineWidth=2;ctx.strokeRect(wx,y+h-26,16,12);}}
