function drawTowers(){const C=G.CASTLE;for(const [tx,ty] of [[C.x0,C.y0],[C.x1,C.y0],[C.x0,C.y1],[C.x1,C.y1]]){const x=(tx+.5)*TILE,y=(ty+.5)*TILE;ctx.fillStyle='rgba(0,0,0,.3)';ctx.beginPath();ctx.ellipse(x+4,y+14,22,8,0,0,7);ctx.fill();ctx.fillStyle='#8d8a82';ctx.fillRect(x-20,y-30,40,42);ctx.fillStyle='#7a766e';for(let j=0;j<3;j++)ctx.fillRect(x-20,y-24+j*14,40,2);ctx.fillStyle='#4a5a8a';ctx.beginPath();ctx.moveTo(x-24,y-28);ctx.lineTo(x,y-62);ctx.lineTo(x+24,y-28);ctx.fill();ctx.strokeStyle='#3a2a18';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x,y-62);ctx.lineTo(x,y-78);ctx.stroke();ctx.fillStyle='#c0392b';ctx.beginPath();ctx.moveTo(x,y-78);ctx.lineTo(x+14+Math.sin(G.time*4)*2,y-74);ctx.lineTo(x,y-70);ctx.fill();}}
function drawFarm(f){const x=f.tx*TILE,y=f.ty*TILE,C=G.CROPS[f.c],kind=C?C.kind:'food';
 if(kind==='food'){const wet=G.cropWet(f);ctx.fillStyle=wet?'#3e2812':'#5a3a1e';ctx.fillRect(x+1,y+1,TILE-2,TILE-2);ctx.fillStyle=wet?'#2e1c0c':'#4a2e16';for(let i=0;i<4;i++)ctx.fillRect(x+2,y+4+i*7,TILE-4,2);if(wet){ctx.fillStyle='rgba(60,120,200,.16)';ctx.fillRect(x+1,y+1,TILE-2,TILE-2);}}
 if(!C)return;const h=4+f.s*6,sw=Math.sin(G.time*2+f.tx)*1.2,ripe=f.s>=3,sh=C.shape;
 if(sh==='sapling'){const g=(f.s+1)/4;ctx.fillStyle='#5a3a1e';ctx.beginPath();ctx.ellipse(x+16,y+27,8,3,0,0,7);ctx.fill();ctx.strokeStyle='#6a4a2a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(x+16,y+27);ctx.lineTo(x+16+sw,y+27-8-g*14);ctx.stroke();ctx.fillStyle='#5aa03a';ctx.beginPath();ctx.arc(x+16+sw,y+25-8-g*14,3+g*5,0,7);ctx.fill();return;}
 if(sh==='flower'){for(let i=0;i<3;i++){const xx=x+7+i*9,yy=y+26;ctx.strokeStyle='#4a8a3a';ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(xx,yy);ctx.lineTo(xx+sw,yy-h);ctx.stroke();if(f.s>=2){ctx.fillStyle=C.col;const r=f.s>=3?3.2:1.8;for(let k=0;k<5;k++){const a=k/5*6.283;ctx.beginPath();ctx.arc(xx+sw+Math.cos(a)*r*.8,yy-h+Math.sin(a)*r*.8,r*.7,0,7);ctx.fill();}ctx.fillStyle='#f0c020';ctx.beginPath();ctx.arc(xx+sw,yy-h,1.4,0,7);ctx.fill();}}return;}
 for(let i=0;i<3;i++){const xx=x+7+i*9;if(sh==='wheat'){ctx.strokeStyle=ripe?'#c9a64a':'#5fbf4a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(xx,y+28);ctx.lineTo(xx+sw,y+28-h);ctx.stroke();if(f.s>=2){ctx.fillStyle=ripe?'#f0d264':'#a8d870';ctx.beginPath();ctx.ellipse(xx+sw,y+26-h,2.5,4.5,0,0,7);ctx.fill();}}
  else if(sh==='carrot'||sh==='root'){ctx.fillStyle='#4fae3a';ctx.beginPath();ctx.moveTo(xx-4,y+26);ctx.lineTo(xx+sw,y+26-h);ctx.lineTo(xx+4,y+26);ctx.fill();if(ripe){ctx.fillStyle=sh==='carrot'?'#ff8a1e':C.col;ctx.beginPath();ctx.arc(xx,y+26,3,0,7);ctx.fill();}}
  else if(sh==='leaf'){ctx.fillStyle=ripe?C.col:'#7ac05a';ctx.beginPath();ctx.arc(xx,y+24,2+f.s*1.6,0,7);ctx.fill();ctx.fillStyle='rgba(255,255,255,.18)';ctx.beginPath();ctx.arc(xx-1,y+23,1+f.s*.7,0,7);ctx.fill();}
  else if(sh==='vine'){ctx.strokeStyle='#3a8a2a';ctx.lineWidth=1.6;ctx.beginPath();ctx.moveTo(xx,y+28);ctx.lineTo(xx+sw,y+28-h);ctx.stroke();ctx.fillStyle='#4a9a3a';ctx.beginPath();ctx.arc(xx+sw,y+26-h*.6,2+f.s,0,7);ctx.fill();if(ripe){ctx.fillStyle=C.col;ctx.beginPath();ctx.arc(xx+2,y+22-h*.4,2.4,0,7);ctx.arc(xx-2,y+25-h*.6,2.2,0,7);ctx.fill();}}
  else if(sh==='tall'||sh==='corn'){ctx.strokeStyle='#5fbf4a';ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(xx,y+28);ctx.lineTo(xx+sw,y+28-h*1.3);ctx.stroke();if(ripe){ctx.fillStyle=C.col;ctx.beginPath();ctx.ellipse(xx+sw+2,y+28-h,2.2,5,0,0,7);ctx.fill();}}
  else if(sh==='pumpkin'){if(i===1){ctx.strokeStyle='#3a8a2a';ctx.lineWidth=1.5;ctx.beginPath();ctx.moveTo(x+4,y+24);ctx.quadraticCurveTo(x+16,y+18,x+28,y+25);ctx.stroke();if(f.s>=2){const r=ripe?7:4;ctx.fillStyle=ripe?C.col:'#8ab040';ctx.beginPath();ctx.ellipse(x+16,y+24,r*1.2,r,0,0,7);ctx.fill();ctx.strokeStyle='rgba(0,0,0,.25)';ctx.beginPath();ctx.moveTo(x+16,y+24-r);ctx.lineTo(x+16,y+24+r);ctx.stroke();}}}
  else{ctx.fillStyle=ripe?'#3aaa3a':'#6ac06a';ctx.beginPath();ctx.arc(xx,y+26-h/2,2+f.s*1.4,0,7);ctx.fill();if(ripe){ctx.fillStyle='#f0f0a0';ctx.beginPath();ctx.arc(xx,y+24-h/2,1.6,0,7);ctx.fill();}}}
 if(ripe){ctx.fillStyle='rgba(255,230,120,'+(.16+Math.sin(G.time*4)*.1)+')';ctx.fillRect(x,y,TILE,TILE);}}
function drawPlot(p){const x=p.tx*TILE,y=p.ty*TILE;if(p.st===0)return;
 if(p.st===1){const g=1-p.t/20;ctx.strokeStyle='#5fbf4a';ctx.lineWidth=2;for(let i=0;i<4;i++){const xx=x+5+i*7;ctx.beginPath();ctx.moveTo(xx,y+27);ctx.lineTo(xx+(i%2?1:-1),y+27-4-g*14);ctx.stroke();}}
 else{for(let i=0;i<4;i++){const xx=x+5+i*7,sw=Math.sin(G.time*2+i)*1.5;ctx.strokeStyle='#c9a64a';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(xx,y+28);ctx.lineTo(xx+sw,y+6);ctx.stroke();ctx.fillStyle='#f0d264';ctx.beginPath();ctx.ellipse(xx+sw,y+8,3,6,0,0,7);ctx.fill();}
  ctx.fillStyle='rgba(255,230,120,'+(.2+Math.sin(G.time*4)*.15)+')';ctx.fillRect(x,y,TILE,TILE);}}
function drawGround(g){const it=g.it,bob=Math.sin(G.time*3+g.y)*2;
 if(g.gold){ctx.fillStyle='#ffd54a';ctx.strokeStyle='#8a6a00';ctx.lineWidth=1.5;for(let i=0;i<3;i++){ctx.beginPath();ctx.ellipse(g.x-5+i*5,g.y-2+bob-(i%2)*3,5,3.5,0,0,7);ctx.fill();ctx.stroke();}return;}
 const c=G.RAR[it.rarity||0].c,pl=Math.sin(G.time*4+g.x)*.5+.5;
 if((it.rarity||0)>=1||!it.stack){const rad=14+(it.rarity||0)*3+pl*4;const gr=ctx.createRadialGradient(g.x,g.y,2,g.x,g.y,rad);gr.addColorStop(0,c+'cc');gr.addColorStop(1,c+'00');ctx.fillStyle=gr;ctx.beginPath();ctx.arc(g.x,g.y,rad,0,7);ctx.fill();}
 if(it.rarity>=4){ctx.fillStyle=c+'44';ctx.fillRect(g.x-3,g.y-70,6,70);}
 ctx.drawImage(G.icon(it).cv,g.x-11,g.y-13+bob,22,22);}
function drawProj(p){if(p.kind==='arrow'){const a=Math.atan2(p.vy,p.vx);ctx.save();ctx.translate(p.x,p.y-8);ctx.rotate(a);ctx.strokeStyle='#5a3d1e';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-10,0);ctx.lineTo(6,0);ctx.stroke();ctx.fillStyle=p.c;ctx.beginPath();ctx.moveTo(9,0);ctx.lineTo(4,-3);ctx.lineTo(4,3);ctx.fill();ctx.restore();}
 else{const gr=ctx.createRadialGradient(p.x,p.y-8,1,p.x,p.y-8,p.r*2);gr.addColorStop(0,'#fff');gr.addColorStop(.35,p.c);gr.addColorStop(1,p.c+'00');ctx.fillStyle=gr;ctx.beginPath();ctx.arc(p.x,p.y-8,p.r*2,0,7);ctx.fill();}}

function drawPProj(p){const a=Math.atan2(p.vy,p.vx);ctx.save();ctx.translate(p.x,p.y-10);ctx.rotate(a);
 if(p.kind==='arrow'||p.kind==='bolt'){ctx.strokeStyle='#6a4626';ctx.lineWidth=p.kind==='bolt'?3:2;ctx.beginPath();ctx.moveTo(-12,0);ctx.lineTo(7,0);ctx.stroke();ctx.fillStyle='#d8dde4';ctx.beginPath();ctx.moveTo(11,0);ctx.lineTo(5,-3.5);ctx.lineTo(5,3.5);ctx.fill();ctx.fillStyle='#e8e0c8';ctx.fillRect(-13,-3,4,6);}
 else{const c={fire:'#ff8a2a',frost:'#9be7ff',storm:'#d0b0ff',light:'#fff3b0'}[p.kind]||'#fff';const gr=ctx.createRadialGradient(0,0,1,0,0,14);gr.addColorStop(0,'#fff');gr.addColorStop(.4,c);gr.addColorStop(1,c+'00');ctx.fillStyle=gr;if(p.kind==='storm'||p.kind==='frost'){ctx.fillRect(-16,-4,28,8);}ctx.beginPath();ctx.arc(0,0,p.kind==='fire'?11:8,0,7);ctx.fill();}
 ctx.restore();}

